use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclfn! {
fn main () -> Result < () > { let matches = Command :: new ("signature-compress") . version ("0.1.0") . about ("Compress macro binding signatures using prime numbers and emojis") . arg (Arg :: new ("input") . short ('i') . long ("input") . value_name ("DIR") . help ("Input directory with declaration files") . required (true)) . arg (Arg :: new ("output") . short ('o') . long ("output") . value_name ("FILE") . help ("Output file for signature mappings")) . arg (Arg :: new ("stats") . short ('s') . long ("stats") . help ("Show compression statistics") . action (clap :: ArgAction :: SetTrue)) . arg (Arg :: new ("optimize") . long ("optimize") . help ("Optimize prime assignments based on frequency") . action (clap :: ArgAction :: SetTrue)) . get_matches () ; let input_dir = matches . get_one :: < String > ("input") . unwrap () ; let output_file = matches . get_one :: < String > ("output") ; let show_stats = matches . get_flag ("stats") ; let optimize = matches . get_flag ("optimize") ; println ! ("🔢 signature-compress: Analyzing macro binding signatures in {}" , input_dir) ; let mut compressor = SignatureCompressor :: new () ; let paths = fs :: read_dir (input_dir) ? ; let mut processed_files = 0 ; for path in paths { let path = path ? . path () ; if path . extension () . and_then (| s | s . to_str ()) == Some ("rs") { let content = fs :: read_to_string (& path) ? ; match compressor . extract_signature (& content) { Ok (signature) => { println ! ("📄 {}: {} → {} ({})" , path . file_name () . unwrap () . to_str () . unwrap () , signature . emoji_key , signature . prime_key , signature . signature_string) ; processed_files += 1 ; } Err (e) => { eprintln ! ("⚠️  Error processing {}: {}" , path . display () , e) ; } } } } println ! ("\n✅ Processed {} files" , processed_files) ; if optimize { println ! ("🎯 Optimizing prime assignments based on frequency...") ; compressor . optimize_prime_assignments () ; println ! ("✅ Prime assignments optimized") ; } if show_stats { let stats = compressor . generate_statistics () ; print_statistics (& stats) ; } if let Some (output_file) = output_file { generate_signature_mappings (& compressor , output_file) ? ; println ! ("📋 Signature mappings written to {}" , output_file) ; } let lookup = SignatureLookup :: from_compressor (& compressor) ; generate_lookup_code (& lookup , & format ! ("{}_lookup.rs" , input_dir)) ? ; demonstrate_compression (& compressor) ; Ok (()) }
}